// Package golog serves as a wrapper around the default log
// package to implement logging levels (Critical, Error,
// Warning, Notice, Info, Debug, Trace). Where a configured level of
// Error would only print messages of type Error and Critical,
// while a level of Trace would print all log messages.

// The package defines a type MyLogger, with methods for
// formatting output, same as the log package, and it also has
// a predefined 'standard' logger with associated logging
// functions that can be used without creating a custom logger.
// This standard logger has a predefined loglevel of Notice
// which means that any logs created by Info or Debug functions
// will be discarded.
package golog

import (
	"fmt"
	"io"
	"log"
	"os"
	"strings"
	"sync"
)

// These flags define the available log levels that can be configured. A level
// of LevelWarning means that only messages of level including and above will
// be displayed (Warning, Error, Critical). So to display log messages of level
// Debug, the log level must be set to LevelDebug.
const (
	LevelNone = iota
	LevelCritical
	LevelError
	LevelWarning
	LevelNotice
	LevelInfo
	LevelDebug
	LevelTrace
)

// These flags define which test to prefix each log entry generated by the
// logger and are copied from the default log package.
const (
	Ldate = 1 << iota
	Ltime
	Lmicroseconds
	Llongfile
	Lshortfile
	LUTC
	Lmsgprefix
	LstdFlags = Ldate | Ltime
)

// flagUnset marks a per-level flag override as absent, meaning the level
// inherits the logger's base flags (see SetLevelFlags / SetFlags).
const flagUnset = -1

// These flags define helper values for logging output
var (
	DefaultOutput    = os.Stdout
	DefaultErrOutput = os.Stderr
	NoOutput         = io.Discard
	std              = New("", LevelNotice, LstdFlags, DefaultOutput, DefaultErrOutput)
)

// A MyLogger represents an active logging object that serves as a wrapper
// around the Logger from the log package. Each logging operation will check
// against the defined loglevel to see if the message should be logged before
// passing it on to the underlying log packets Logger.
type MyLogger struct {
	log   *log.Logger
	elog  *log.Logger
	level int
	name  string
	// mu serialises the per-level flag swap performed in emit so that
	// concurrent calls at different levels do not observe each other's
	// temporary flags on the shared underlying log.Logger.
	mu sync.Mutex
	// levelFlags holds an optional flag override per log level. An entry of
	// flagUnset means the level inherits the underlying logger's base flags.
	// By default LevelDebug and LevelTrace are initialised to the base flags
	// plus Lshortfile so their output records the originating file and line.
	levelFlags [LevelTrace + 1]int
}

// A map to define packet specific loggers such that a packet
// can check if a custom logger exists and if so use it, and otherwise
// fallback to a default logger.
var (
	customLoggers   = make(map[string]*MyLogger)
	customLoggersMu sync.RWMutex
)

// Setup a new logger for a given reference.
// Intended usage is to specify a custom logger for a packet.
func Set(name, displayname string, level, flags int, output, errOutput io.Writer) {
	customLoggersMu.Lock()
	defer customLoggersMu.Unlock()
	if val, ok := customLoggers[name]; ok {
		val.level = level
		if flags > 0 {
			val.SetFlags(flags)
		}
		if output != nil {
			val.SetOutput(output)
		}
		if errOutput != nil {
			val.SetErrOutput(errOutput)
		}
		if displayname != "" {
			val.SetDisplayName(displayname)
		}
	} else {
		customLoggers[name] = New(displayname, level, flags, output, errOutput)
	}
}

// Get a custom logger if it exists, otherwise return default logger.
func Get(name string) *MyLogger {
	// If no name is specified return the default logger
	if name == "" {
		return std
	}
	customLoggersMu.RLock()
	if val, ok := customLoggers[name]; ok {
		customLoggersMu.RUnlock()
		return val
	}
	customLoggersMu.RUnlock()

	customLoggersMu.Lock()
	defer customLoggersMu.Unlock()
	// Double-check after acquiring write lock
	if val, ok := customLoggers[name]; ok {
		return val
	}
	newLogger := New(name, LevelNotice, LstdFlags, DefaultOutput, DefaultErrOutput)
	parts := strings.Split(name, "/")
	newLogger.SetDisplayName(parts[len(parts)-1] + " ")
	customLoggers[name] = newLogger
	return newLogger
}

func Names() []string {
	customLoggersMu.RLock()
	defer customLoggersMu.RUnlock()
	names := make([]string, 0, len(customLoggers))
	for l := range customLoggers {
		names = append(names, l)
	}
	return names
}

func SetAll(level, flags int, output, errOutput io.Writer) {
	customLoggersMu.Lock()
	defer customLoggersMu.Unlock()
	for _, lg := range customLoggers {
		if output == nil {
			output = DefaultOutput
		}
		if errOutput == nil {
			errOutput = DefaultErrOutput
		}
		lg.level = level
		lg.SetFlags(flags)
		lg.SetOutput(output)
		lg.SetErrOutput(errOutput)
	}
}

// For scenarios when we just want to export the underlying logger.
func Logger() *log.Logger {
	return std.log
}

// For scenarios when we just want to export the underlying logger.
func (ml *MyLogger) Logger() *log.Logger {
	return ml.log
}

// New creates a new MyLogger. The level variable sets the loglevel which should
// be used to filter what is logged. The flags variable is passed directly to
// the underlying log package to set Logger flags. The output variable sets the
// destination to which log data will be written.
//
// As a convenience for debugging, the LevelDebug and LevelTrace flag overrides
// are initialised to flags|Lshortfile so that debug and trace messages record
// the originating file and line. Use SetLevelFlags / ClearLevelFlags to change
// or remove per-level overrides.
func New(name string, level, flags int, output io.Writer, errOutput io.Writer) *MyLogger {
	// Hack to avoid extra space when not using a custom name
	if name != "" {
		name += " "
	}
	ml := &MyLogger{
		log:   log.New(output, "", flags),
		elog:  log.New(errOutput, "", flags),
		level: level,
		name:  name,
	}
	for i := range ml.levelFlags {
		ml.levelFlags[i] = flagUnset
	}
	// Default: debug and trace logs include the source file and line.
	ml.levelFlags[LevelDebug] = flags | Lshortfile
	ml.levelFlags[LevelTrace] = flags | Lshortfile
	return ml
}

func SetFlags(flag int) {
	std.log.SetFlags(flag)
	std.elog.SetFlags(flag)
}

func Flags() int {
	return std.log.Flags()
}

func (ml *MyLogger) SetFlags(flag int) *MyLogger {
	ml.log.SetFlags(flag)
	ml.elog.SetFlags(flag)
	return ml
}

func (ml *MyLogger) Flags() int {
	return ml.log.Flags()
}

// SetLevelFlags overrides the log flags used for a single level, leaving the
// base flags (SetFlags) untouched for all other levels. Passing a level
// outside the valid range is a no-op. Use ClearLevelFlags to drop an override
// and have the level inherit the base flags again.
func SetLevelFlags(level, flags int) {
	std.SetLevelFlags(level, flags)
}

// ClearLevelFlags removes a per-level flag override so the level inherits the
// base flags again.
func ClearLevelFlags(level int) {
	std.ClearLevelFlags(level)
}

// LevelFlags reports the effective flags for a level: the per-level override
// if one is set, otherwise the base flags.
func LevelFlags(level int) int {
	return std.LevelFlags(level)
}

// SetLevelFlags overrides the log flags used for a single level, leaving the
// base flags (SetFlags) untouched for all other levels. Passing a level
// outside the valid range is a no-op.
func (ml *MyLogger) SetLevelFlags(level, flags int) *MyLogger {
	if level < 0 || level >= len(ml.levelFlags) {
		return ml
	}
	ml.mu.Lock()
	ml.levelFlags[level] = flags
	ml.mu.Unlock()
	return ml
}

// ClearLevelFlags removes a per-level flag override so the level inherits the
// base flags again.
func (ml *MyLogger) ClearLevelFlags(level int) *MyLogger {
	if level < 0 || level >= len(ml.levelFlags) {
		return ml
	}
	ml.mu.Lock()
	ml.levelFlags[level] = flagUnset
	ml.mu.Unlock()
	return ml
}

// LevelFlags reports the effective flags for a level: the per-level override
// if one is set, otherwise the base flags.
func (ml *MyLogger) LevelFlags(level int) int {
	if level < 0 || level >= len(ml.levelFlags) {
		return ml.Flags()
	}
	ml.mu.Lock()
	f := ml.levelFlags[level]
	ml.mu.Unlock()
	if f == flagUnset {
		return ml.Flags()
	}
	return f
}

