func (ml *MyLogger) SetDisplayName(name string) *MyLogger {
	if !strings.HasSuffix(name, " ") {
		name += " "
	}
	ml.name = name
	return ml
}

// emit writes msg to w applying any per-level flag override. The flag swap is
// serialised by ml.mu so concurrent emits at different levels do not observe
// each other's temporary flags. The calldepth of 3 accounts for the call chain
// user code -> level method -> emit -> log.Output so that Lshortfile/Llongfile
// report the file and line of the originating call site.
func (ml *MyLogger) emit(level int, w *log.Logger, msg string) {
	ml.mu.Lock()
	defer ml.mu.Unlock()
	if f := ml.levelFlags[level]; f != flagUnset && f != w.Flags() {
		old := w.Flags()
		w.SetFlags(f)
		defer w.SetFlags(old)
	}
	w.Output(3, msg)
}

// With returns a child logger that prepends prefix to every message after
// the parent's display name, e.g.:
//
//	smb/server [192.0.2.7:49832] [Error] connection reset
//
// The child copies the parent's log level, flags, per-level flag overrides,
// prefix and output destinations at the time of the call, but owns fresh
// underlying log.Logger instances, so subsequent SetFlags/SetOutput/
// SetLogLevel/SetLevelFlags calls on either parent or child do not affect the
// other.
//
// Children are not registered in the package logger registry: golog.Set,
// golog.Get, golog.Names and golog.SetAll neither see nor update them.
// Intended for short-lived per-connection or per-session context such as
// a remote address.
func (ml *MyLogger) With(prefix string) *MyLogger {
	if prefix != "" && !strings.HasSuffix(prefix, " ") {
		prefix += " "
	}
	ml.mu.Lock()
	levelFlags := ml.levelFlags
	ml.mu.Unlock()
	return &MyLogger{
		log:        log.New(ml.log.Writer(), ml.log.Prefix(), ml.log.Flags()),
		elog:       log.New(ml.elog.Writer(), ml.elog.Prefix(), ml.elog.Flags()),
		level:      ml.level,
		name:       ml.name + prefix,
		levelFlags: levelFlags,
	}
}

func (ml *MyLogger) SetPrefix(prefix string) *MyLogger {
	ml.log.SetPrefix(prefix)
	return ml
}

func (ml *MyLogger) Prefix() string {
	return ml.log.Prefix()
}

func (ml *MyLogger) Output(calldepth int, s string) error {
	return ml.log.Output(calldepth, s)
}

func (ml *MyLogger) Debug(v ...interface{}) {
	if ml.level >= LevelDebug {
		ml.emit(LevelDebug, ml.log, fmt.Sprintf(ml.name+"[Debug] %v", v...))
	}
}

func (ml *MyLogger) Debugln(v ...interface{}) {
	if ml.level >= LevelDebug {
		ml.emit(LevelDebug, ml.log, fmt.Sprintf(ml.name+"[Debug] %v", v...))
	}
}

func (ml *MyLogger) Debugf(format string, v ...interface{}) {
	if ml.level >= LevelDebug {
		ml.emit(LevelDebug, ml.log, fmt.Sprintf(ml.name+"[Debug] "+format, v...))
	}
}

